<div class="adm-quick-grid"><div class="adm-quick-card"><div class="adm-quick-label">Code</div><strong><?= e($partner['partner_code']) ?></strong></div><div class="adm-quick-card"><div class="adm-quick-label">Status</div><strong><?= e(str_replace('_',' ',$partner['status'])) ?></strong></div><div class="adm-quick-card"><div class="adm-quick-label">Model</div><strong><?= e(ucfirst($partner['partnership_type'])) ?></strong></div><div class="adm-quick-card"><div class="adm-quick-label">Public listing</div><strong><?= e(str_replace('_',' ',$partner['public_status'])) ?></strong></div></div>
<div class="adm-form-section"><div class="adm-form-section-title">Partnership status</div><form method="post" action="<?= base_url('/admin/partners/'.$partner['id'].'/status') ?>"><?= csrf_field() ?><select class="form-select" name="status" style="max-width:320px;display:inline-block"><option value="new_lead" <?= $partner['status']==='new_lead'?'selected':'' ?>>New lead</option><option value="agreement_pending" <?= $partner['status']==='agreement_pending'?'selected':'' ?>>Agreement pending</option><option value="onboarding" <?= $partner['status']==='onboarding'?'selected':'' ?>>Onboarding</option><option value="active" <?= $partner['status']==='active'?'selected':'' ?>>Active</option><option value="paused" <?= $partner['status']==='paused'?'selected':'' ?>>Paused</option><option value="expired" <?= $partner['status']==='expired'?'selected':'' ?>>Expired</option><option value="terminated" <?= $partner['status']==='terminated'?'selected':'' ?>>Terminated</option></select> <button class="tcm-btn primary">Save Status</button></form></div>
<div class="adm-form-section"><div class="adm-form-section-title">Public directory publication</div><form method="post" action="<?= base_url('/admin/partners/'.$partner['id'].'/public-status') ?>"><?= csrf_field() ?><select class="form-select" name="public_status" style="max-width:320px;display:inline-block"><option value="draft" <?= $partner['public_status']==='draft'?'selected':'' ?>>Draft</option><option value="pending_review" <?= $partner['public_status']==='pending_review'?'selected':'' ?>>Pending review</option><option value="published" <?= $partner['public_status']==='published'?'selected':'' ?>>Published</option><option value="rejected" <?= $partner['public_status']==='rejected'?'selected':'' ?>>Rejected</option></select> <button class="tcm-btn primary">Save Listing Status</button></form><p class="muted">Only active partners can be published. Legal, tax, bank, and agreement fields stay private.</p></div>
<div class="adm-form-section"><div class="adm-form-section-title">Authorized users</div><?php if(!$members): ?><p class="muted">No account has accepted the invitation to <?= e($partner['email']??'—') ?> yet.</p><form method="post" action="<?= base_url('/admin/partners/'.$partner['id'].'/invite') ?>"><?= csrf_field() ?><button class="tcm-btn secondary sm">Resend Owner Invitation</button></form><?php else: ?><div class="adm-table-wrap"><table class="tcm-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Finance access</th><th>Status</th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><?= e($m['name']) ?></td><td><?= e($m['email']) ?></td><td><?= e(ucfirst(str_replace('partner_','',$m['member_role']))) ?></td><td><?= (int)$m['can_view_finance']?'Yes':'No' ?></td><td><?= e($m['status']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></div>
<div class="adm-form-section"><div class="adm-form-section-title">Recent requests</div><?php if(!$requests): ?><p class="muted">No service requests.</p><?php else: ?><div class="adm-table-wrap"><table class="tcm-table"><thead><tr><th>Type</th><th>Subject</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><?= e($r['request_type']) ?></td><td><?= e($r['subject']) ?></td><td><?= e($r['status']) ?></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></div>
<div class="adm-form-section"><div class="adm-form-section-title">Partner batches</div><?php if(!$batches): ?><p class="muted">No batch requests.</p><?php else: ?><div class="adm-table-wrap"><table class="tcm-table"><thead><tr><th>Batch</th><th>Course</th><th>Dates</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($batches as $b): ?><tr><td><?= e($b['batch_name']) ?></td><td><?= e($b['course_title']??'—') ?></td><td><?= e($b['starts_on']??'—') ?> – <?= e($b['ends_on']??'—') ?></td><td><?= e(str_replace('_',' ',$b['status'])) ?></td><td><form method="post" action="<?= base_url('/admin/partners/batches/'.$b['id']) ?>"><?= csrf_field() ?><select name="status" class="form-select form-select-sm"><option value="admissions_open">Admissions Open</option><option value="upcoming">Upcoming</option><option value="active">Active</option><option value="cancelled">Cancelled</option></select><button class="tcm-btn primary sm">Apply</button></form></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></div>
<div class="adm-form-section"><div class="adm-form-section-title">Financial ledger records</div><?php if(!$ledger): ?><p class="muted">No ledger rows. Financial totals will remain empty until verified transactions are recorded.</p><?php else: ?><div class="adm-table-wrap"><table class="tcm-table"><thead><tr><th>Id</th><th>Type</th><th>Collection owner</th><th>Gross</th><th>Eligible</th><th>Partner / TCM</th><th>Status</th></tr></thead><tbody><?php foreach($ledger as $l): ?><tr><td>#<?= (int)$l['id'] ?></td><td><?= e($l['entry_type']) ?></td><td><?= e($l['collection_owner']) ?></td><td>₹<?= number_format((float)$l['gross_amount'],2) ?></td><td>₹<?= number_format((float)$l['eligible_amount'],2) ?></td><td>₹<?= number_format((float)$l['partner_entitlement'],2) ?> / ₹<?= number_format((float)$l['tcm_entitlement'],2) ?></td><td><?= e($l['status']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></div>
